print(json.dumps({'preservedFiles':len(expected),'app':'only record wiring','key':'only gate wiring','publicAssets':'identical in dist','protectedHashes':{p:expected[p] for p in ['src/chain.ts','src/wallet.ts','package.json','package-lock.json','index.html']}},indent=2))
